package ca.emilybelnavis.mcmods.economy.simulation.macro;

import ca.emilybelnavis.mcmods.economy.api.*;
import ca.emilybelnavis.mcmods.economy.api.Identifiers.*;
import ca.emilybelnavis.mcmods.economy.fx.*;
import ca.emilybelnavis.mcmods.economy.journal.*;
import ca.emilybelnavis.mcmods.economy.simulation.model.*;
import ca.emilybelnavis.mcmods.economy.simulation.prime.CurrencyPrimes;
import ca.emilybelnavis.mcmods.economy.storage.FoundationStore;
import java.math.*;
import java.time.Instant;
import java.util.*;
import static ca.emilybelnavis.mcmods.economy.simulation.model.Rational.*;

/** Trusted worker control API. Modes/configurations never rewrite prior rows or publish rates directly. */
public final class MacroControls {
    private MacroControls(){}
    private static final Journal.Kind SCHEDULE=new Journal.Kind("economy:a8","economy:a8/macro/schedule");
    public enum Mode { AUTO,PAUSED,MANUAL }
    public record Policy(UUID id,WorldId world,long revision,long effectiveMillis,Mode mode,MacroModel.Config config,
                         Map<EconomyCurrency,BigDecimal> primeDeltas,Map<EconomyCurrency,BigDecimal> fxMultipliers) {
        public Policy{Objects.requireNonNull(id);Objects.requireNonNull(world);Objects.requireNonNull(mode);Objects.requireNonNull(config);primeDeltas=decimals(primeDeltas);fxMultipliers=decimals(fxMultipliers);if(revision<1||effectiveMillis<0)throw new IllegalArgumentException("Macro control policy");
            if(mode==Mode.MANUAL){if(!primeDeltas.keySet().equals(new HashSet<>(EconomyCurrency.all()))||!fxMultipliers.keySet().equals(primeDeltas.keySet()))throw new IllegalArgumentException("Complete manual currency vector required");for(var value:primeDeltas.values())if(value.abs().compareTo(new BigDecimal("0.001"))>0||value.stripTrailingZeros().scale()>6)throw new IllegalArgumentException("Manual prime delta exceeds0.001 APR");for(var value:fxMultipliers.values())if(value.signum()<=0||value.precision()>34||value.scale()>18||value.scale()< -18)throw new IllegalArgumentException("Manual FX multiplier domain");for(var a:fxMultipliers.values())for(var b:fxMultipliers.values())if(!within(of(a).divide(of(b)),of("0.995"),of("1.005")))throw new IllegalArgumentException("Manual ordered-pair step exceeds0.5percent");}
            else if(!primeDeltas.isEmpty()||!fxMultipliers.isEmpty())throw new IllegalArgumentException("Automatic/paused policy has no manual outcomes");}
    }
    public record ManualOutput(Map<EconomyCurrency,BigDecimal> primes,Map<EconomyCurrency,BigDecimal> fx,Rational alpha,List<String> explanations,String hash){public ManualOutput{primes=decimals(primes);fx=decimals(fx);Objects.requireNonNull(alpha);explanations=List.copyOf(explanations);if(alpha.compareTo(ZERO)<0||alpha.compareTo(ONE)>0||hash==null||!hash.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Manual output hash");}}
    public static Optional<Policy> find(JournalEngine.ReadView reads,WorldId world,long at){if(at<0)throw new IllegalArgumentException("Macro policy time");var rows=reads.query("SELECT payload FROM macro_control_policies WHERE world_id=? AND effective_ms<=? ORDER BY effective_ms DESC LIMIT 1",List.of(world.value().toString(),Long.toString(at)),1);return rows.isEmpty()?Optional.empty():Optional.of(MacroFacts.decodePolicy(rows.getFirst().get("payload")));}
    public static Policy current(JournalEngine.ReadView reads,WorldId world,long at){return find(reads,world,at).orElseThrow(()->new IllegalArgumentException("MACRO_POLICY_UNAVAILABLE"));}
    public static JournalEngine.Commit prepareInitial(JournalEngine.ReadView reads,WorldId world,UUID actualOperation,Policy policy){if(!policy.world().equals(world)||policy.revision()!=1||policy.mode()==Mode.MANUAL||!reads.query("SELECT id FROM macro_control_policies LIMIT 1",List.of(),1).isEmpty())throw new IllegalArgumentException("Initial macro policy conflict");return prepared(actualOperation,policy,null,-1,-1);}
    public static Policy schedule(FoundationStore store,Policy policy,Instant trustedNow){return schedule(store,policy,trustedNow,new SystemActorId(MacroFacts.stable("actor|"+store.snapshot().worldId().value())));}
    public static Policy schedule(FoundationStore store,Policy policy,Instant trustedNow,ActorId actor){Objects.requireNonNull(actor);var world=store.snapshot().worldId();if(!world.equals(policy.world()))throw new IllegalArgumentException("Macro policy world");UUID operation=MacroFacts.stable("schedule|"+world.value()+"|"+policy.id());String payload=MacroFacts.encode(policy);var request=new Journal.CanonicalRequest(1,Map.of("policy",MacroFacts.digest(payload)));
        var registration=new JournalEngine.Registration(1,(i,r)->{if(!request.equals(i.request()))throw new IllegalArgumentException("Macro control original intent");try{var prior=validateSchedule(r,world,policy,trustedNow);return prepared(operation,policy,prior,trustedNow.toEpochMilli(),frontier(r,trustedNow.toEpochMilli()));}catch(IllegalArgumentException|ArithmeticException invalid){String reason=String.valueOf(invalid.getMessage());return new JournalEngine.Reject(new Journal.Result(1,"MACRO_POLICY_REJECTED",reason.length()>1024?reason.substring(0,1024):reason));}});
        var result=new JournalEngine(store,(a,k)->a.equals(actor)&&k.equals(SCHEDULE),Map.of(SCHEDULE,registration)).submit(new Journal.Intent(new OperationId(operation),new RequestId(operation),actor,SCHEDULE,request,null,null));if(result.status()!=Journal.Status.COMMITTED)throw new IllegalArgumentException("Macro control schedule: "+result.result().code()+": "+result.result().payload());return policy;}
    static Policy validateSchedule(JournalEngine.ReadView reads,WorldId world,Policy policy,Instant now){var activation=CurrencyPrimes.activation(reads,world).orElseThrow(()->new IllegalArgumentException("Macro activation missing"));long frontier=frontier(reads,now.toEpochMilli());
        var rows=reads.query("SELECT payload FROM macro_control_policies WHERE world_id=? ORDER BY revision DESC LIMIT 1",List.of(world.value().toString()),1);if(rows.isEmpty())throw new IllegalArgumentException("Initial macro control missing");var prior=MacroFacts.decodePolicy(rows.getFirst().get("payload"));
        if(policy.revision()!=Math.addExact(prior.revision(),1)||policy.effectiveMillis()<=prior.effectiveMillis()||policy.effectiveMillis()<=frontier||policy.effectiveMillis()<activation.firstEventMillis()||(policy.effectiveMillis()-activation.firstEventMillis())%CurrencyPrimes.DAY_MILLIS!=0)throw new IllegalArgumentException("Macro policies append only at strictly future event boundaries");
        if(Long.parseLong(reads.query("SELECT COUNT(*) AS pending FROM macro_control_policies WHERE world_id=? AND effective_ms>?",List.of(world.value().toString(),Long.toString(frontier)),1).getFirst().get("pending"))>=16)throw new IllegalArgumentException("Macro pending policy bound");
        var matching=reads.query("SELECT payload FROM macro_control_policies WHERE config_id=? AND config_revision=? LIMIT 1",List.of(policy.config().id().toString(),Integer.toString(policy.config().revision())),1);if(!matching.isEmpty()&&!MacroFacts.decodePolicy(matching.getFirst().get("payload")).config().equals(policy.config()))throw new IllegalArgumentException("Immutable macro config changed");
        if(policy.mode()==Mode.MANUAL){if(prior.mode()==Mode.AUTO)throw new IllegalArgumentException("Pause before scheduling manual rate outcome");validateKnownManualPredecessor(reads,world,policy,frontier);}
        return prior;
    }
    private static void validateKnownManualPredecessor(JournalEngine.ReadView reads,WorldId world,Policy proposed,long frontier){var active=current(reads,world,frontier);var a=CurrencyPrimes.activation(reads,world).orElseThrow();var fx=FxService.at(reads,frontier);
        if(active.mode()==Mode.AUTO||!CurrencyPrimes.ready(reads,world,frontier)||!MacroActivation.ready(reads,world,frontier)||fx==null||fx.mode()==EffectiveFxSnapshot.Mode.LEGACY_DAILY)throw new IllegalArgumentException("MANUAL_PREDECESSOR_NOT_CAPTURED: wait for a completed paused rate event");
        var primes=new EnumMap<EconomyCurrency,BigDecimal>(EconomyCurrency.class);for(var c:a.currencies())primes.put(c,CurrencyPrimes.current(reads,world,c,frontier).orElseThrow(()->new IllegalArgumentException("Manual prime predecessor unavailable")).primeApr());Map<EconomyCurrency,BigDecimal> rates=fx.rates();
        for(var row:reads.query("SELECT payload FROM macro_control_policies WHERE world_id=? AND effective_ms>? ORDER BY effective_ms LIMIT 16",List.of(world.value().toString(),Long.toString(frontier)),16)){var scheduled=MacroFacts.decodePolicy(row.get("payload"));if(scheduled.mode()==Mode.AUTO)throw new IllegalArgumentException("MANUAL_PREDECESSOR_NOT_CAPTURED: a future automatic interval precedes this outcome");if(scheduled.mode()==Mode.MANUAL){var output=apply(scheduled,primes,rates,a.anchors(),a.reference());primes.clear();primes.putAll(output.primes());rates=output.fx();}}
        apply(proposed,primes,rates,a.anchors(),a.reference());
    }
    /** Exact relative manual intent; reject invalid absolute/pairwise outcomes rather than silently alter it. */
    public static ManualOutput apply(Policy policy,Map<EconomyCurrency,BigDecimal> priorPrimes,Map<EconomyCurrency,BigDecimal> priorFx,Map<EconomyCurrency,BigDecimal> anchors,EconomyCurrency reference){
        if(policy.mode()==Mode.AUTO)throw new IllegalArgumentException("Automatic mode requires the frozen model output");requireManifest(priorPrimes,false);requireManifest(priorFx,true);requireManifest(anchors,true);if(priorFx.get(reference).compareTo(BigDecimal.ONE)!=0||anchors.get(reference).compareTo(BigDecimal.ONE)!=0)throw new IllegalArgumentException("Permanent FX reference must remainone");validateVector(priorFx,priorFx,anchors);
        var primes=new EnumMap<EconomyCurrency,BigDecimal>(EconomyCurrency.class);var rates=new EnumMap<EconomyCurrency,BigDecimal>(EconomyCurrency.class);
        for(var c:EconomyCurrency.all()){var old=priorPrimes.get(c);if(old.signum()<0||old.compareTo(new BigDecimal("0.25"))>0||old.stripTrailingZeros().scale()>6)throw new IllegalArgumentException("Manual prior prime outside bounds");var value=policy.mode()==Mode.MANUAL?old.add(policy.primeDeltas().get(c)):old;if(value.signum()<0||value.compareTo(new BigDecimal("0.25"))>0||value.subtract(old).abs().compareTo(new BigDecimal("0.001"))>0)throw new IllegalArgumentException("Manual prime outcome outside0..0.25: "+c);primes.put(c,value.setScale(6,RoundingMode.HALF_EVEN));
            var multiplier=policy.mode()==Mode.MANUAL?of(policy.fxMultipliers().get(c)).divide(of(policy.fxMultipliers().get(reference))):ONE;rates.put(c,c==reference?BigDecimal.ONE.setScale(12):of(priorFx.get(c)).multiply(multiplier).decimal(12));}
        validateVector(rates,priorFx,anchors);var alpha=policy.mode()==Mode.PAUSED?ZERO:ONE;var explanations=List.of(policy.mode()==Mode.PAUSED?"PAUSED_HOLD":"EXACT_MANUAL_OUTCOME");String canonical=MacroFacts.encode(policy)+"|"+new TreeMap<>(priorPrimes)+"|"+new TreeMap<>(priorFx)+"|"+new TreeMap<>(anchors)+"|"+reference+"|"+primes+"|"+rates+"|"+alpha;return new ManualOutput(primes,rates,alpha,explanations,MacroFacts.digest(canonical));
    }
    private static void validateVector(Map<EconomyCurrency,BigDecimal> vector,Map<EconomyCurrency,BigDecimal> prior,Map<EconomyCurrency,BigDecimal> anchors){for(var c:EconomyCurrency.all()){if(!within(of(vector.get(c)),of("0.000000000001"),of(1_000_000)))throw new IllegalArgumentException("Manual FX representation");for(var d:EconomyCurrency.all()){var ratio=of(vector.get(c)).divide(of(vector.get(d)));var old=of(prior.get(c)).divide(of(prior.get(d)));var anchor=of(anchors.get(c)).divide(of(anchors.get(d)));if(!within(ratio.divide(old),of("0.995"),of("1.005"))||!within(ratio.divide(anchor),of("0.5"),of(2)))throw new IllegalArgumentException("Manual FX ordered-pair/anchor bound after rounding: "+c+"/"+d);}}}
    static long frontier(JournalEngine.ReadView reads,long now){if(now<0)throw new IllegalArgumentException("Negative macro control UTC");long value=now;for(String sql:List.of("SELECT observed_wall_ms AS value FROM economic_metadata WHERE singleton=1","SELECT MAX(frontier_ms) AS value FROM economic_systems","SELECT MAX(active_observed_ms) AS value FROM economic_systems","SELECT observed_wall_ms AS value FROM financial_calendar WHERE singleton=1","SELECT last_effective_ms AS value FROM financial_calendar WHERE singleton=1","SELECT MAX(effective_ms) AS value FROM financial_deadline_events","SELECT observed_ms AS value FROM activity_activation WHERE singleton=1")){var rows=reads.query(sql,List.of(),1);if(!rows.isEmpty()&&rows.getFirst().get("value")!=null)value=Math.max(value,Long.parseLong(rows.getFirst().get("value")));}return value;}
    private static JournalEngine.Commit prepared(UUID actualOperation,Policy policy,Policy previous,long scheduled,long frontier){String payload=MacroFacts.encode(policy);var records=new ArrayList<Journal.Record>();records.add(new Journal.Record(MacroFacts.POLICY,1,payload));if(previous!=null)records.add(new Journal.Record(MacroFacts.SCHEDULE,1,MacroFacts.encode(new MacroFacts.Schedule(policy.world(),policy.id(),previous.id(),scheduled,frontier))));return new JournalEngine.Commit(records,new Journal.Result(1,"MACRO_POLICY_RECORDED",policy.id().toString()),tx->tx.execute("INSERT INTO macro_control_policies VALUES(?,?,?,?,?,?,?,?,?,?,?)",List.of(policy.id().toString(),policy.world().value().toString(),Long.toString(policy.revision()),Long.toString(policy.effectiveMillis()),policy.config().id().toString(),Integer.toString(policy.config().revision()),actualOperation.toString(),previous==null?"":previous.id().toString(),Long.toString(scheduled),Long.toString(frontier),payload)));}
    private static boolean within(Rational value,Rational low,Rational high){return value.compareTo(low)>=0&&value.compareTo(high)<=0;}
    private static Map<EconomyCurrency,BigDecimal> decimals(Map<EconomyCurrency,BigDecimal> values){Objects.requireNonNull(values);var result=new EnumMap<EconomyCurrency,BigDecimal>(EconomyCurrency.class);for(var e:values.entrySet()){Objects.requireNonNull(e.getKey());Objects.requireNonNull(e.getValue());result.put(e.getKey(),e.getValue());}return Collections.unmodifiableMap(result);}
    private static void requireManifest(Map<EconomyCurrency,BigDecimal> values,boolean positive){if(!values.keySet().equals(new HashSet<>(EconomyCurrency.all()))||values.values().stream().anyMatch(v->v==null||(positive?v.signum()<=0:v.signum()<0)))throw new IllegalArgumentException("Complete positive currency vector required");}
}
